changeSet.sql:
create or alter procedure [graph].[AssetBrowser_Impact] @assets dbo.UidTable readonly ,@resourceId int ,@hopCount int ,@intersects dbo.Ids readonly ,@includeHierarchyBadges bit = 1 ,@includeOwnershipBadges bit = 1 ,@includeRelationBadges bit = 1 ,@direction char(1) = 'A' -- (A)all, (B)ackward, (F)orward ,@assets dbo.Ids readonly ,@hierarchyKey varchar(50) = null -- If this value is populated, you should link all relationships to this key. Not populated during initial load of AB. ,@predicateUid uniqueidentifier = null ,@isAdmin bit ,@initialSaltValue int = -1 as begin set nocount on;
declare @restrictedTypes table ([Type] int) insert into @restrictedTypes values (15) if @includeHierarchyBadges = 0 begin insert into @restrictedTypes values (3), (4) end
-- Tables that will contain the data to return. This is the final data that should be loaded into these tables. drop table if exists #edges; create table #edges ( [from] varchar(100), [to] varchar(100), back varchar(7) default('#cccccc'), [text] nvarchar(250), predicateIdsJson varchar(max), linksJson varchar(max) );
drop table if exists #nodes; create table #nodes ( hop int, initial bit, hierarchyKey varchar(500), focal bit, leaf bit, childCount int default(0), template varchar(50), [key] varchar(100), [group] varchar(100), [text] nvarchar(max), assetUid uniqueidentifier, assetId bigint, assetTypeId int, assetTypeUid uniqueidentifier, backAmount decimal(2,1), back varchar(7), icon varchar(250), class int, actionCount int, useAsTransformation bit default(0), hasAssetReadAccess bit default(1), hasResponsibilityReadAccess bit default(1), isSubjectInTransformation bit default(1) ); create nonclustered index IX_TempNodes_HierarchyKey on #nodes (hierarchyKey asc); create nonclustered index IX_TempNodes_Group on #nodes ([group] asc); create nonclustered index IX_TempNodes_Key on #nodes ([key] asc);
drop table if exists #a; create table #a (Salt int, Position int, Initial bit default(0), ID bigint, AssetTypeID int) create clustered index cx_a on #a(ID,Salt);
drop table if exists #temppredicate; create table #temppredicate (PredicateID int) create clustered index cx_temppredicate on #temppredicate(PredicateID);
drop table if exists #i; create table #i (Position int, IntersectID int, PredicateID int, PredicateUid uniqueidentifier, [Text] nvarchar(250), PredicateType int, SubjectHierarchyKey varchar(50), SubjectKey varchar(50), SubjectSalt int, SubjectID bigint, ObjectHierarchyKey varchar(50), ObjectKey varchar(50), ObjectSalt int, ObjectID bigint)
create clustered index cx_i on #i(IntersectID,Position); create nonclustered index IX_i_ObjectSalt_include on #i (ObjectSalt) include (ObjectID); create nonclustered index IX_i_SubjectSalt_include on #i (SubjectSalt) include (SubjectID); create nonclustered index IX_i_SubjectHierarchyKey_include on #i (SubjectHierarchyKey,ObjectHierarchyKey) include (IntersectID,Position);
declare @c int = 1, @salt int = LEFT(CAST(RAND()*1000000000+999999 AS INT),3) -- Random 3 digit number as salt
if @initialSaltValue > 0 begin set @salt = @initialSaltValue end
insert into #a (Salt, Position, Initial, ID) select @salt, 0, 1, ID from @assets O inner join Asset A on A.Uid = O.Uid;
drop table if exists #hopIntersectIds; create table #hopIntersectIds([Id] [int]) create clustered index cx_hopIntersectIds on #hopIntersectIds(Id);
insert into #hopIntersectIds select distinct Id from @intersects
insert into #temppredicate(predicateId) select P.Id from [predicate] P where ((@predicateUid is null) OR (@predicateUid is not null and P.Uid = @predicateUid)) and P.[Type] between 1 and 13;
while @c <= @hopCount begin declare @newSalt int = LEFT(CAST(RAND()*1000000000+999999 AS INT),3)
declare @hasSameSidedRelationship bit = 0; if exists(select top 1 1 from #a H inner join [intersect] I on I.ObjectAssetID = H.ID inner join [IntersectType] IT on IT.ID = I.IntersectTypeID inner join #temppredicate P on IT.PredicateID = P.PredicateID left join #hopIntersectIds hp on hp.id = I.ID where I.SubjectAssetTypeId = I.ObjectAssetTypeId and hp.id is null) begin set @hasSameSidedRelationship = 1; end
if @direction = 'A' or @direction = 'F' begin insert into #i (Position, IntersectID, PredicateID, PredicateUid, [Text], PredicateType, SubjectHierarchyKey, SubjectKey, SubjectSalt, SubjectID, ObjectHierarchyKey, ObjectKey, ObjectSalt, ObjectID) select @c, I.ID IntersectID, P.ID PredicateID, P.Uid PredicateUid, P.Name PredicateName, P.Type PredicateType, 'T|' + cast(@salt as varchar(3)) + '|' + cast(I.SubjectAssetTypeID as varchar(15)), 'A|' + cast(@salt as varchar(3)) + '|' + cast(I.SubjectAssetID as varchar(20)), @salt, I.SubjectAssetID as SubjectID, 'T|' + cast(@newSalt as varchar(3)) + '|' + cast(I.ObjectAssetTypeID as varchar(15)), 'A|' + cast(@newSalt as varchar(3)) + '|' + cast(I.ObjectAssetID as varchar(20)), @newSalt, I.ObjectAssetID as ObjectID from #a H inner join [intersect] I on I.SubjectAssetID = H.ID inner join [IntersectType] IT on I.IntersectTypeID = It.ID inner join #temppredicate Pd on IT.PredicateID = Pd.PredicateID inner join [predicate] P on P.ID = pd.PredicateID left join #hopIntersectIds hp on hp.id = I.ID where hp.Id is null; end
if @direction = 'A' or @direction = 'B' begin insert into #i (Position, IntersectID, PredicateID, PredicateUid, [Text], PredicateType, SubjectHierarchyKey, SubjectKey, SubjectSalt, SubjectID, ObjectHierarchyKey, ObjectKey, ObjectSalt, ObjectID) select @c, I.ID IntersectID, P.ID PredicateID, P.Uid PredicateUid, P.Inverse PredicateInverse, P.Type PredicateType, 'T|' + cast(@newSalt as varchar(3)) + '|' + cast(I.SubjectAssetTypeID as varchar(15)), 'A|' + cast(@newSalt as varchar(3)) + '|' + cast(I.SubjectAssetID as varchar(20)), @newSalt, I.SubjectAssetID as SubjectID, 'T|' + cast(@salt as varchar(3)) + '|' + cast(I.ObjectAssetTypeID as varchar(15)), 'A|' + cast(@salt as varchar(3)) + '|' + cast(I.ObjectAssetID as varchar(20)), @salt, I.ObjectAssetID as ObjectID from #a H inner join [intersect] I on I.ObjectAssetID = H.ID inner join [IntersectType] IT on I.IntersectTypeID = It.ID and IT.SubjectAssetTypeId <> IT.ObjectAssetTypeId inner join #temppredicate Pd on IT.PredicateID = Pd.PredicateID inner join [predicate] P on P.ID = pd.PredicateID left join #hopIntersectIds hp on hp.id = I.ID where hp.Id is null;
if @hasSameSidedRelationship = 1 begin -- When relationship has same Asset Type on Object and Subject side, one side should be shown as a different node so we use @newSalt+1 to create a new node
insert into #i (Position, IntersectID, PredicateID, PredicateUid, [Text], PredicateType, SubjectHierarchyKey, SubjectKey, SubjectSalt, SubjectID, ObjectHierarchyKey, ObjectKey, ObjectSalt, ObjectID) select @c, I.ID IntersectID, P.ID PredicateID, P.Uid PredicateUid, P.Inverse PredicateInverse, P.Type PredicateType, 'T|' + cast(@newSalt+1 as varchar(3)) + '|' + cast(I.SubjectAssetTypeID as varchar(15)), 'A|' + cast(@newSalt+1 as varchar(3)) + '|' + cast(I.SubjectAssetID as varchar(20)), @newSalt+1, I.SubjectAssetID as SubjectID, 'T|' + cast(@salt as varchar(3)) + '|' + cast(I.ObjectAssetTypeID as varchar(15)), 'A|' + cast(@salt as varchar(3)) + '|' + cast(I.ObjectAssetID as varchar(20)), @salt, I.ObjectAssetID as ObjectID from #a H inner join [intersect] I on I.ObjectAssetID = H.ID inner join [IntersectType] IT on I.IntersectTypeID = It.ID and IT.SubjectAssetTypeId = IT.ObjectAssetTypeId inner join #temppredicate Pd on IT.PredicateID = Pd.PredicateID inner join [predicate] P on P.ID = pd.PredicateID left join #hopIntersectIds hp on hp.id = I.ID where hp.Id is null; end end
insert into #hopIntersectIds(Id) select IntersectID from #i
insert into #a (Salt, Position, ID) select distinct @newSalt, @c, ObjectID from #i where ObjectSalt = @newSalt
if @hasSameSidedRelationship = 1 begin insert into #a (Salt, Position, ID) select distinct @newSalt+1, @c, SubjectID from #i where SubjectSalt = @newSalt+1 end
insert into #a (Salt, Position, ID) select distinct @newSalt, @c, SubjectID from #i where SubjectSalt = @newSalt
set @salt = @newSalt set @c = @c + 1 end
drop table if exists #temppredicate;
update T set T.AssetTypeID = S.AssetTypeID from #a T inner join Asset S on S.ID = T.ID
-- if this is a hop, get rid of the starting root node if @hierarchyKey is not null and @predicateUid is not null begin delete #a where Initial = 1 end
-- Add asset type node as parent levels.
drop table if exists #tempa; select Salt, Initial, Position, AssetTypeID into #tempa from #a group by Salt, Initial, Position, AssetTypeID
create clustered index cx_tempa on #tempa(AssetTypeID,Salt);
insert into #nodes (hop, initial, hierarchyKey, focal, leaf, template, [key], [text], assetTypeId, assetTypeUid, backAmount, back, icon, class) select O.Salt as hop, O.Initial, 'T|' + cast(O.Salt as varchar(3)) + '|' + cast(A.ID as varchar) as hierarchyKey, cast(iif(O.Initial= 1, 1, 0) as bit) as focal, 0 as leaf, 'PortGroup' as template, 'T|' + cast(O.Salt as varchar(3)) + '|' + cast(A.ID as varchar) as [key], A.Name as [text], A.ID as assetTypeId, A.Uid as assetTypeUid, 0 as backAmount, coalesce(S.IconBackColor, '#000000') as back, coalesce(S.Icon, 'fa-book') as icon, A.class from #tempa O inner join AssetType A on A.ID = O.AssetTypeID left join AssetTypeStyle S on S.ID = A.ID order by O.Position
-- Add asset nodes. insert into #nodes (hop, initial, hierarchyKey, focal, leaf, template, [key], [group], [text], assetUid, assetId, assetTypeId, assetTypeUid, backAmount, back, icon, class) select O.Salt as hop, O.Initial, 'T|' + cast(O.Salt as varchar(3)) + '|' + cast(A.AssetTypeID as varchar) as hierarchyKey, cast(iif(O.Initial = 1, 1, 0) as bit) as focal, 1 as leaf, '' as template, 'A|' + cast(O.Salt as varchar(3)) + '|' + cast(A.ID as varchar) as [key], 'T|' + cast(O.Salt as varchar(3)) + '|' + cast(A.AssetTypeID as varchar) as [group], A.DisplayValue as [text], A.uid as assetUid, A.ID as assetId, A.assetTypeId, A.assetTypeUid, 0.2 as backAmount, A.BackColor as back, A.icon, A.AssetTypeClass as class from #a O inner join AssetDetail A on A.ID = O.ID order by O.Position
drop table if exists #a; drop table if exists #tempa; -- Add edges drop table if exists #group_i;
select I.SubjectHierarchyKey as [from], I.ObjectHierarchyKey as [to], try_cast(string_agg(cast([text] as nvarchar(max)), ', ') as nvarchar(250)) [text] into #group_i from (select distinct SubjectHierarchyKey,ObjectHierarchyKey, [text] from #i ) I group by I.SubjectHierarchyKey, I.ObjectHierarchyKey;
insert into #edges ([from], [to], [text], predicateIdsJson, linksJson) select case when @hierarchyKey is not null and @direction = 'F' then @hierarchyKey else [from] end, case when @hierarchyKey is not null and @direction = 'B' then @hierarchyKey else [to] end, [text] as [text], ( SELECT CONCAT('[', ( select STRING_AGG(predicateId, ', ') from ( select distinct predicateId from #i where SubjectHierarchyKey = g.[from] and ObjectHierarchyKey = g.[to] ) p ), ']') ), ( select distinct intersectId as id, SubjectKey as [from], ObjectKey as [to], predicateId, predicateUid, predicateType from #i where SubjectHierarchyKey = g.[from] and ObjectHierarchyKey = g.[to] for json path ) from #group_i g;
drop table if exists #i; drop table if exists #group_i;
-- Update properties on nodes before returning. update T set T.childCount = C.[Count] from #nodes T cross apply ( select count(1) as [Count] from #nodes where [group] = T.[key] ) C
if @hierarchyKey is null and @predicateUid is null begin update #nodes set template = 'FocalPortGroup' where initial = 1 and [group] is null end
-- Update assets that have open actions update T set T.actionCount = C.[Count] from #nodes T inner join Asset A on A.ID = T.assetId cross apply ( select count(1) as [Count] from Issue I where I.AssetID = A.ID and CompletedOn is null and exists (select 1 from workflow.Item where Object = 'Issue' and ObjectID = I.ID) ) C;
-- Update asset read permissions drop table if exists #TempUserPremission;
with rs as ( select AssetTypeID from #nodes group by AssetTypeID ) select distinct P.AssetID, H.AssetTypeID, P.PermissionsBitMask into #TempUserPremission from rs H cross apply dbo.UserAssetPermissions(@resourceId, H.AssetTypeID) P;
create index ix_TempUserPremission on #TempUserPremission(AssetTypeID, AssetID);
IF EXISTS(SELECT 1 FROM #TempUserPremission) BEGIN update H set HasAssetReadAccess = iif(P.PermissionsBitMask & 1 = 1, 1, 0), HasResponsibilityReadAccess = iif(P.PermissionsBitMask & 32 = 32, 1, 0) from #nodes H inner join #TempUserPremission P on P.AssetTypeID = H.AssetTypeID AND P.AssetID = H.assetId;
update H set HasAssetReadAccess = iif(P.PermissionsBitMask & 1 = 1, 1, 0), HasResponsibilityReadAccess = iif(P.PermissionsBitMask & 32 = 32, 1, 0) from #nodes H inner join #TempUserPremission P on P.AssetTypeID = H.AssetTypeID AND P.AssetID = 0; END
drop table if exists #TempUserPremission;
-- Get ownership badge data, IF we are supposed to include. drop table if exists #GroupedOwners; create table #GroupedOwners (hierarchyKey varchar(500), id int, [text] nvarchar(250), ResourceID int) create nonclustered index IX_TempGroupedOwners_hierarchyKey on #GroupedOwners (hierarchyKey asc);
if @includeOwnershipBadges = 1 begin drop table if exists #respAssets;
select distinct assetId into #respAssets from #nodes where assetId is not null
drop table if exists #assetsResponsibilityDetail select RD.ResponsibilityTypeID,RD.ResponsibilityTypeName, RD.ResourceID,RD.ApplyToType,RD.AssetID,RD.IsVisible into #assetsResponsibilityDetail from ResponsibilityDetail RD inner join #respAssets ra on RD.AssetID = ra.assetId where RD.ApplyToType = 0 AND RD.IsVisible = 1;
drop table if exists #respAssets;
create clustered index cx_assetsResponsibilityDetail on #assetsResponsibilityDetail(assetId,ApplyToType,IsVisible);
insert into #GroupedOwners select IH.hierarchyKey, R.ResponsibilityTypeID as id, R.ResponsibilityTypeName as [text], R.ResourceID from #nodes IH inner join Asset A on A.ID = IH.assetId inner join #assetsResponsibilityDetail R on (R.AssetID = IH.assetId and R.ApplyToType = 0 and R.IsVisible = 1) group by IH.hierarchyKey, R.ResponsibilityTypeID, R.ResponsibilityTypeName, R.ResourceID
drop table if exists #assetsResponsibilityDetail;
drop table if exists #respAssetTypes select distinct AssetTypeID into #respAssetTypes from #nodes where AssetTypeID is not null
drop table if exists #assetTypesResponsibilityDetail select RD.ResponsibilityTypeID,RD.ResponsibilityTypeName, RD.ResourceID,RD.ApplyToType,RD.AssetTypeID,RD.IsVisible into #assetTypesResponsibilityDetail from ResponsibilityDetail RD inner join #respAssetTypes RT ON RT.assetTypeId = RD.AssetTypeID where RD.ApplyToType = 1 AND RD.IsVisible = 1;
drop table if exists #respAssetTypes;
insert into #GroupedOwners select IH.hierarchyKey, R.ResponsibilityTypeID as id, R.ResponsibilityTypeName as [text], R.ResourceID from #nodes IH inner join Asset A on A.ID = IH.assetId inner join #assetTypesResponsibilityDetail R on (R.ApplyToType = 1 and R.AssetTypeID = A.AssetTypeID and R.IsVisible = 1) left join #GroupedOwners G on G.hierarchyKey = IH.hierarchyKey and G.id = R.ResponsibilityTypeID and G.ResourceID = R.ResourceID where G.id is null group by IH.hierarchyKey, R.ResponsibilityTypeID, R.ResponsibilityTypeName, R.ResourceID;
drop table if exists #assetTypesResponsibilityDetail; end;
-- Return data to client. select * from #nodes order by hop, hierarchyKey, [group]; -- 1. Asset nodes select * from #edges; -- 2. Edges
drop table if exists #edges;
-- 3. Predicate/Owner badges for root assets. select H.hierarchyKey, H.hierarchyKey as predictableId, ( select id, [text], count(1) as [count] from #GroupedOwners where hierarchyKey = H.hierarchyKey group by id, [text] for json path ) as ownersJson, ( select case @includeRelationBadges when 1 then ( select * from ( select P.ID as predicateId, P.Uid as predicateUid, P.Name as [predicate], 1 as direction, count(1) as [count] from #nodes IH inner join Asset A on A.ID = IH.assetId inner join [intersect] I on I.SubjectAssetID = A.ID inner join [IntersectType] IT on IT.ID = I.IntersectTypeID Inner Join [predicate] P on P.ID = IT.PredicateID and P.[Type] not in (select [Type] from @restrictedTypes) left join #hopIntersectIds hp on hp.Id = I.ID where IH.hierarchyKey = H.hierarchyKey and hp.Id is null group by P.ID, P.Uid, P.Name union all select P.ID as predicateId, P.Uid as predicateUid, P.Inverse as [predicate], 2 as direction, count(1) as [count] from #nodes IH inner join Asset A on A.ID = IH.assetId inner join [intersect] I on I.ObjectAssetID = A.ID inner join [IntersectType] IT on IT.ID = I.IntersectTypeID Inner Join [predicate] P on P.ID = IT.PredicateID and P.[Type] not in (select [Type] from @restrictedTypes) left join #hopIntersectIds hp on hp.Id = I.ID where IH.hierarchyKey = H.hierarchyKey and hp.Id is null group by P.ID, P.Uid, P.Inverse ) OO for json path ) else null end ) as relationsJson from #nodes H where H.[group] is null;
drop table if exists #nodes; drop table if exists #GroupedOwners; drop table if exists #hopIntersectIds; end
